fn solve(n: i8) -> Vec<char> {
    // Cast to u8 so we can do digit arithmetic without worrying about negative values.
    let n = n as u8;

    // Pre-allocate exactly 6 slots: 'A','B','C' + three decimal digits
    let mut result = Vec::with_capacity(6);

    // First three characters
    result.push('A');
    result.push('B');
    result.push('C');

    // Extract and push each decimal digit
    result.push((n / 100 + b'0') as char);
    result.push(((n / 10) % 10 + b'0') as char);
    result.push(((n % 10) + b'0') as char);

    result
}

